json_text <- function(x) {
  parts <- strsplit(x, "\n", fixed = TRUE)[[1]]
  parts <- vapply(
    parts,
    function(part) {
      part <- gsub("\\", "\\\\", part, fixed = TRUE)
      gsub("\"", "\\\"", part, fixed = TRUE)
    },
    character(1)
  )
  paste0("\"", paste(parts, collapse = "\\n"), "\"")
}
