}
one <- function() {
  cost <- matrix(c(0, 1, 4, NA, 0, 2, 3, NA, 0), 3, byrow = TRUE)
  extractPath(allShortestPaths(cost), 1, 3)

}
value <- one()
elapsed <- numeric(20)
for (i in seq_len(20)) {
  t0 <- as.numeric(Sys.time())
  one()
  elapsed[[i]] <- as.numeric(Sys.time()) - t0
}
cat(sprintf('{"value":%s,"median_ms":%.17g}\n', json_num(value), median(elapsed) * 1000))

